  "decode.kind.moeActive.title": "MoE – aktive Parameter",
  "decode.kind.moeActive.desc": "Aktive Parameter pro Token (z. B. A3B = 3B aktiv). Rechenaufwand ≈ aktive Parameter; VRAM ≈ Gesamtparameter.",
  "decode.kind.quantAWQ.title": "Quantisierung · AWQ",
