  "decode.kind.base.title": "Basismodell",
  "decode.kind.base.desc": "Nur vortrainiert – NICHT instruction-tuned. Zum Feinabstimmen gedacht, nicht zum direkten Chatten.",
  "decode.kind.coder.title": "Auf Code spezialisiert",
