  "decode.kind.math.desc": "Abgestimmt auf mathematisches Schlussfolgern.",
  "decode.kind.vision.title": "Vision / multimodal",
  "decode.kind.vision.desc": "Verarbeitet Bilder + Text (VLM).",
  "decode.kind.embedding.title": "Einbettungen",
  "decode.kind.embedding.desc": "Erzeugt Vektoren für Suche / RAG – kein Chat-Modell.",
  "decode.kind.reranker.title": "Reranker",
  "decode.kind.reranker.desc": "Bewertet / sortiert Dokumente für das Retrieval – kein Generator.",
  "decode.kind.reasoning.title": "Reasoning",
  "decode.kind.reasoning.desc": "Ein Reasoning- / „Thinking“-Modell (R1, QwQ, distill…) – stark bei mehrstufigen Problemen.",
  "decode.kind.sizeClass.title": "Größenklasse",
  "decode.kind.sizeClass.desc": "Relative Größenstufe (mini / small / large …).",
  "decode.kind.speed.title": "Auf Tempo optimiert",
  "decode.kind.speed.desc": "Abgestimmt auf niedrige Latenz / hohen Durchsatz (turbo / flash / lite).",
  "decode.kind.context.title": "Kontextlänge",
