  "decode.kind.date.title": "Release-Stand",
  "decode.kind.date.desc": "Datumscode für Release / Training (z. B. 2507 ≈ 2025-07).",
  "decode.kind.format.title": "Format",
  "decode.kind.format.desc": "Paket- / Laufzeitformat (HF Transformers, MLX, ONNX …).",
  "decode.kind.agentic.title": "Agentisch / Toolnutzung",
  "decode.kind.agentic.desc": "Abgestimmt auf Agenten-Workflows und Tool- / Funktionsaufrufe.",
  "decode.kind.uncensored.title": "Unzensiert",
  "decode.kind.uncensored.desc": "Sicherheitsfilter reduziert oder entfernt (abliterated). Verweigert seltener – verantwortungsvoll einsetzen.",
  "decode.kind.method.title": "Tuning- / Merge-Methode",
